125	function update(dt){
126	  if($('#modalBackdrop')&&!$('#modalBackdrop').classList.contains('hidden')||$('#journalBackdrop')&&!$('#journalBackdrop').classList.contains('hidden'))return;
127	  let dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+ (window.touchDX||0);
128	  let dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+(window.touchDY||0);
129	  const mag=Math.hypot(dx,dy);
130	  if(mag){
131	    dx/=mag;dy/=mag;
132	    const sprint=(keys.Shift||keys.shift)&&player.stamina>4;
133	    const speed=(sprint?.62:.43);
134	    if(sprint){player.stamina=Math.max(0,player.stamina-dt*15);}else{player.stamina=Math.min(100,player.stamina+dt*9);}
135	    player.x=Math.max(-.82,Math.min(.82,player.x+dx*speed*dt));
136	    player.y=Math.max(-.68,Math.min(.68,player.y+dy*speed*dt));
137	    player.a=Math.atan2(dy,dx);player.walk+=dt*(sprint?13:9);
138	  }else{player.stamina=Math.min(100,player.stamina+dt*12);}
139	  nearest=null;let nd=1;
140	  Object.entries(stations).forEach(([k,s])=>{if(s.done)return;let d=Math.hypot(player.x-s.x,player.y-s.y);if(d<.19&&d<nd){nearest=k;nd=d;}});
141	  const el=$('#interaction');el.classList.toggle('visible',!!nearest);
142	  if(nearest){$('#interactionName').textContent=stations[nearest].name;$('#interactionType').textContent=stations[nearest].type;}

